def getProjection(v, basis):
    """
    Compute the projection of vector v onto the vector space generated by the
    given orthogonal basis. The vectors of the basis are given as row vectors.

    Parameters
    ----------
    v : array
        1-dimensional array representing the vector v.
    basis : array
        2-dimensional array with the row vectors of the orthogonal basis.

    Returns
    -------
    array
        1-dimensional array representing the projection of v.
    """
    res = np.zeros_like(v)
    for bi in basis:
        res += (np.dot(v, bi) / np.dot(bi, bi)) * bi
    return res


def getWigglesProjection(weights, signaturesProj, diffs, diffsEps, lyrEps):
    """
    signaturesProj contains the projections as row vectors
    """
    # Get wiggles in the layer
    norm = np.linalg.norm(signaturesProj, axis=1)
    wigglesLyr = (lyrEps / norm)[:, np.newaxis] * signaturesProj

    # Get wiggles in the input
    coeff, _, _, _ = np.linalg.lstsq(diffs.T, wigglesLyr.T, rcond=None)
    return diffsEps * coeff.T


def getOrthogonalBasis(V):
    """
    Compute an orthogonal basis for the space generated by the vectors given
    by the rows of matrix V.

    Parameters
    ----------
    V : array
        2-dimensional array with the row vectors.

    Returns
    -------
    array
        Orthogonal basis given by the rows of the returned matrix.
    """
    rk = np.linalg.matrix_rank(V)
    q, _ = np.linalg.qr(V.T)
    return q[:, 0:rk].T


def getLocalMatrixAndBias(weights, biases, x0):
    """
    Given the weights and biases up to a certain layer, find the equivalent matrix and bias
    around the vicinity of an input x.

    Parameters
    ----------
    weights:
        A list of weights for the known layers (each of them a 2D array).
    biases:
        A list of biases for the known layers (each of them a 1D array).
    x0:
        A 1D array of inputs (of dimension equal to the second dimension of weights[0])
        OR a 2D array which consists of a vector of inputs (along the first dimension)

    Returns
    -------
    M
        A 2D array representing the local matrix
        OR a 3D array representing one matrix per input (along the first dimension)
    b
        A 1D array representing the local bias vector
        OR a 2D array representing one bias per input (along the first dimension)
    """

    # Special case if x0 is not vectorized
    if len(x0.shape) < 2:
        M, b = getLocalMatrixAndBias(weights, biases, np.array([x0]))
        return M[0], b[0]

    MM = []
    bb = []
    for x0i in x0:
        M = weights[0].copy()
        b = biases[0].copy()
        x = np.matmul(x0i, M) + b
        for layer_id in range(1, len(weights)):
            M_hat = weights[layer_id].copy()
            M_hat[x < 0] = (
                0  # already applies the ReLU kind of, discounts all weight values <0 like ReLU, only if all in this row are <0 then inactive neuron?
            )
            x = np.matmul(x, M_hat) + biases[layer_id]
            b = np.matmul(b, M_hat) + biases[layer_id]
            M = np.matmul(M, M_hat)

        MM.append(M)
        bb.append(b)

    return np.array(MM), np.array(bb)


def getOrthogonalBasisForInnerLayerSpace(x, weights, biases, l, eps):
    """
    Given the input x to the DNN, compute an orthogonal basis for the vector
    space generated by the linear neighbourhood of x after the l first layers,
    inclusive.

    Parameters
    ----------
    x : array
        1-dimensional array representing an input to the DNN.
    weights : array
        List of weights corresponding to the hidden layers. The i-th element in
        the list is a 2-dimensional array with the weights of the incoming
        connections to the neurons in the i-th hidden layer.
    biases : array
        List of biases corresponding to the hidden layers. The i-th element in
        the list is a 1-dimensional array with the biases of the neurons in the
        i-th hidden layer.
    l : int
        Number of hidden layers to consider.
    eps : float
        "Infinitesimal" variation used for computing the vector space after the
        first l layers. This value should be small enough so that varying each
        coordinate at the input does not cross the boundary of the linear
        neighbourhood of x.

    Returns
    -------
    B : array
        Orthogonal basis of the vector space after the first l layers. The
        basis is given by the rows of the returned matrix.
    diffs : array
        Let f_{1..l} be the function that evaluates the first l layers of the
        DNN. Also, let y = f_{1..l}(x) and h_i = f_{1..l}(x + eps * e_i), where
        e_i is the i-th canonical vector.
        diffs is a 2-dimensional array representing a matrix where the i-th row
        is the vector h_i - y.
    """
    n = np.prod(x.shape)
    if l > 0:
        M, b = getLocalMatrixAndBias(weights[0:l], biases[0:l], x)
    else:
        M = np.identity(n, dtype=np.double)
        b = np.zeros_like(x)

    # y = f_{1..l}(x)
    y = np.matmul(x, M) + b
    y *= y > 0

    # h_i = f_{1..l}(x + eps * e_i)
    xdx = (eps * np.identity(n, dtype=np.float64)) + x
    hidVecs = np.matmul(xdx, M) + b
    hidVecs *= hidVecs > 0

    # Find orthogonal basis for the space generated by all h_i - y
    diffs = hidVecs - y
    B = getOrthogonalBasis(diffs)

    return B, diffs


# ==========
# Main function for sign recovery
def recoverSign(
    args,
    model,
    recovered_weights,
    recovered_biases,
    target_signature,
    target_layer,
    critical_points,
):
    EPS_IN = 1e-6
    EPS_LYR = 1e-8
    EPS_ZERO = 1e-12
    SAMPLE_DIFF_ZERO = 1e-13

    nExpNeg = 0
    nExpPos = 0
    sampleL = []
    sampleR = []

    orig_weights, orig_biases = getAllWeightsAndBiases(model)

    for point_index, point in enumerate(critical_points):
        # print(f"Processing critical point {point_index + 1}/{len(critical_points)}")

        # Get number of active neurons in each hidden layer
        yi = point
        active = []
        for lyr in range(target_layer):
            yi = np.matmul(yi, recovered_weights[lyr]) + recovered_biases[lyr]
            yi *= yi > 0
            active.append(len(yi[yi > 0]))
        active = np.array(active)

        # Get orthogonal basis for the input vector space for the target
        # layer and restrict its dimension to that of the minimum dimension
        # in previous layers
        B, diffs = getOrthogonalBasisForInnerLayerSpace(
            point, recovered_weights, recovered_biases, target_layer, EPS_IN
        )
        # assumes that reducing the basis to the size of the smallest layer will capture the most critical aspects of the network's transformations.
        if target_layer > 0:
            B = B[: np.min(active)]

        # Get projection of the neuron's signature onto the space above
        proj = getProjection(target_signature, B)
        signaturesProj = np.array([proj * (np.abs(proj) > EPS_ZERO)])

        # Get wiggle
        try:
            wigglesi = getWigglesProjection(
                target_signature, signaturesProj, diffs, EPS_IN, EPS_LYR
            )
        except Exception:
            print("Wiggle computation failed.")
            continue

        # ==========
        # Evaluate DNN
        # ==========
        fx = predict_manual_fast(
            np.array([point - wigglesi[0], point + wigglesi[0], point]),
            orig_weights,
            orig_biases,
        )

        # ==========
        # Samples
        # ==========
        sample_diff_cnt = 0
        sL = np.linalg.norm(fx[0] - fx[2])
        sR = np.linalg.norm(fx[1] - fx[2])
        # Check that samples are "far" from each other
        # We break off a neuron’s sign recovery if more than 30 iterations of this error are seen consecutively
        if (np.abs(sL - sR) < SAMPLE_DIFF_ZERO) or np.abs(sL - sR) == np.nan:
            print(
                "np.abs(sL - sR) < SAMPLE_DIFF_ZERO: ",
                np.abs(sL - sR),
                SAMPLE_DIFF_ZERO,
            )
            sample_diff_cnt += 1
            # Put some code here for failure and returning put catch phrase in code that calls recoverSign
            if sample_diff_cnt > 15:
                sampleL = np.array(sampleL)
                sampleR = np.array(sampleR)
                print("Neuron's signature is most likely wrong.")
                print(
                    "No valid critical points could be computed for the sign extraction."
                )
                return (
                    0,
                    nExpNeg,
                    nExpPos,
                    sampleL,
                    sampleR,
                )
            continue
        # If we have passed the check correctly at least once again we can reset the count because we only count continuous errors.
        sample_diff_cnt = 0
        # Collect samples
        sampleL.append(sL)
        sampleR.append(sR)

        # Confidence interval
        if sL > sR:
            nExpNeg += 1
        elif sL < sR:
            nExpPos += 1

    sampleL = np.array(sampleL)
    sampleR = np.array(sampleR)

    # 4: Number of experiments that decided sign +
    m4 = np.sum((sampleL / sampleR) < 1.0)

    signm4 = (
        (-2.0 * (m4 < (len(sampleL)) / 2) + 1.0) if m4 != ((len(sampleL)) / 2) else 0.0
    )

    print("Number of experiments that decided sign +", m4)
    print("Sign of the neuron is", signm4)

    return m4, signm4
